import { Suspense } from 'react'
import { cacheLife } from 'next/cache'
import { getProducts } from '@/lib/data'

type CatalogSearchParams = Promise<{ category?: string }>

export default function CatalogPage({
  searchParams,
}: {
  searchParams: CatalogSearchParams
}) {
  return (
    <main>
      <h1>Catalog</h1>
      <Suspense fallback={<p>Loading category...</p>}>
        <CategoryResults searchParams={searchParams} />
      </Suspense>
    </main>
  )
}

async function CategoryResults({
  searchParams,
}: {
  searchParams: CatalogSearchParams
}) {
  const { category = 'featured' } = await searchParams
  const { heading, products } = await getCategoryView(category)

  return (
    <section>
      <h2>{heading}</h2>
      <ul>
        {products.map((product) => (
          <li key={product}>{product}</li>
        ))}
      </ul>
    </section>
  )
}

async function getCategoryView(category: string) {
  'use cache'
  cacheLife('hours')

  return {
    heading: category === 'sale' ? 'Products on sale' : 'Featured products',
    products: await getProducts(category),
  }
}
